1	#!/usr/bin/env node
2	// The Claudinite SELF-TEST — "can Claudinite run here?", and nothing else.
3	//
4	// Deliberately NOT a conformance check. `check_the_world` judges the repo's
5	// CONTENT against the rules; this judges whether the MACHINERY that would run
6	// those rules is intact. A repo can be perfectly conformant and still have a
7	// broken mount, a hook pointing at a file that no longer exists, or a pack whose
8	// manifest the loader silently drops — and every one of those is invisible to a
9	// content check, because a rule that never runs reports nothing.
10	//
11	// WHY IT EXISTS. Every fleet-wide failure this corpus has had was of that shape:
12	//
13	//   #397  inject-pack-prose imported a module that did not exist, so every
14	//         active pack's RULES.md was silently un-injected, fleet-wide, for days
15	//   #518  loadConfig dropped the mount stamp, so the nightly converge self-skipped
16	//         everywhere and no run ever said so
17	//   #555  a required manifest field landed with no migration; consumer packs
18	//         stopped validating, and (because normalizeManifest rebuilds `rules`
19	//         from the scoped lists) their checks stopped running silently
20	//   #424  five mounted skill links dangled on main, unnoticed
21	//
22	// None was caught by canon CI, because the canon's own tree is always already
23	// correct. All four are assertions below, and each would have fired on the first
24	// session after the change — on the member, where the damage was.
25	//
26	// CONTRACT. Fast (no network, no clone), read-only, and it never throws: a probe
27	// that cannot run is a FAILED probe with the reason attached, never a crash that
28	// takes the session-start orchestrator down with it.
29	//
30	// Pure core + thin I/O shell, the corpus idiom: `report()` takes plain probe
31	// results and decides the outcome, so the whole decision surface is testable
32	// without a repo on disk.
33	
34	import { existsSync, readFileSync, readdirSync, lstatSync, realpathSync } from 'node:fs';
35	import { join, dirname } from 'node:path';
36	import { fileURLToPath, pathToFileURL } from 'node:url';
37	
38	export const MOUNT = '.claudinite/shared';
39	export const CHECKS = '.claudinite-checks.json';
40	export const SETTINGS = '.claude/settings.json';
41	export const SCHEDULER = '.github/workflows/claudinite-scheduler.yml';
42	
43	// A probe result. `ok: null` means NOT APPLICABLE — the thing this probe would
44	// judge is legitimately absent (no scheduler in a repo that never cut over, no
45	// local packs declared). Not-applicable is never a failure; conflating the two
46	// is how a check earns its reputation for crying wolf.
47	export const pass = (id) => ({ id, ok: true });
48	export const skip = (id, why) => ({ id, ok: null, detail: why });
49	export const fail = (id, detail, fix) => ({ id, ok: false, detail, fix });
50	
51	// The verdict over a probe set. Exit code is the caller's business — this only
52	// says what happened, so both callers (a session-start step that must never
53	// block, and a strict CI/bootstrap run that must) read the same result.
54	export function report(probes) {
55	  const failures = probes.filter((p) => p.ok === false);
56	  const ran = probes.filter((p) => p.ok !== null).length;
57	  return {
58	    ok: failures.length === 0,
59	    ran,
60	    skipped: probes.length - ran,
61	    failures,
62	    summary: failures.length
63	      ? `Claudinite self-test: ${failures.length} of ${ran} probes FAILED — ${failures.map((f) => f.id).join(', ')}`
64	      : `Claudinite self-test: ${ran} probes passed.`,
65	  };
66	}
67	
68	// --- the probes ------------------------------------------------------------
69	// Each takes an injected `io` ({ exists, read, dirs, resolves }) so the whole
70	// set runs against an in-memory tree in tests. No probe imports another's
71	// result: a broken mount must not cascade into eight confusing failures, so
72	// each says one true thing about the repo in front of it.
73	
74	export function probeMount(io) {
75	  if (!io.exists(MOUNT)) return skip('mount', 'no vendored mount — this is the canon itself, or a repo that has not adopted');
76	  if (!io.exists(`${MOUNT}/engine/checks/check_the_world.mjs`)) {
77	    return fail('mount', `${MOUNT} exists but carries no engine`, 're-run the update task, or bootstrap this repo — the mount is incomplete');
78	  }
79	  return pass('mount');
80	}
81	
82	export function probeStamp(io) {
83	  const raw = io.read(CHECKS);
84	  if (raw === null) return fail('stamp', `${CHECKS} is missing`, 'run bootstrap --init to write the declaration');
85	  let cfg;
86	  try { cfg = JSON.parse(raw); } catch (e) {
87	    return fail('stamp', `${CHECKS} is not valid JSON: ${e.message}`, 'fix the JSON syntax — nothing can read the declaration until it parses');
88	  }
89	  if (!io.exists(MOUNT)) return skip('stamp', 'no vendored mount to stamp');
90	  const s = cfg.claudinite;
91	  if (!s || typeof s.updated !== 'string' || !s.updated) {
92	    return fail('stamp', 'the mount is present but carries no claudinite.updated stamp',
93	      'the update flows read this to decide what to apply — a missing stamp makes the task self-skip forever (#518)');
94	  }
95	  return pass('stamp');
96	}
97	
98	// The #555 probe. A manifest the loader rejects means that pack's rules never
99	// run — silently, because normalizeManifest rebuilds `rules` from the scoped
100	// lists and an unvalidated manifest contributes none.
101	export function probePackManifests(loaded) {
102	  if (!loaded) return skip('pack-manifests', 'the pack loader could not be reached from here');
103	  if (loaded.errors?.length) {
104	    const first = loaded.errors[0];
105	    return fail('pack-manifests', `${loaded.errors.length} pack(s) failed to load or validate — first: ${first.what ?? first}`,
106	      first.fix ?? 'fix the manifest — a pack that does not validate contributes no rules, so its checks stop running with no other symptom');
107	  }
108	  if (!loaded.packs?.length) return fail('pack-manifests', 'no packs were discovered at all', 'check the mount and the declaration — a session with no packs enforces nothing');
109	  return pass('pack-manifests');
110	}
111	
112	export function probeHookTargets(io) {
113	  const raw = io.read(SETTINGS);
114	  if (raw === null) return skip('hook-targets', 'no .claude/settings.json');
115	  let cfg;
116	  try { cfg = JSON.parse(raw); } catch (e) {
117	    return fail('hook-targets', `${SETTINGS} is not valid JSON: ${e.message}`, 'fix the JSON — the harness silently runs no hooks when its settings will not parse');
118	  }
119	  const missing = [];
120	  for (const entries of Object.values(cfg.hooks ?? {})) {
121	    for (const entry of Array.isArray(entries) ? entries : []) {
122	      for (const hook of entry.hooks ?? []) {
123	        const cmd = String(hook.command ?? '');
124	        // The path inside the command, with the harness's variable resolved.
125	        const m = cmd.match(/\$CLAUDE_PROJECT_DIR\/(\S+)/);
126	        if (m && !io.exists(m[1])) missing.push(m[1]);
127	      }
128	    }
129	  }
130	  if (missing.length) {
131	    return fail('hook-targets', `${missing.length} hook command(s) point at files that do not exist: ${missing.join(', ')}`,
132	      're-run the update task to converge the wiring — a hook whose target is missing fails silently every session (#397)');
133	  }
134	  return pass('hook-targets');
135	}
136	
137	export function probeSkillLinks(io) {
138	  const root = '.claude/skills';
139	  if (!io.exists(root)) return skip('skill-links', 'no mounted skills');
140	  const dangling = io.dangling(root);
141	  if (dangling.length) {
142	    return fail('skill-links', `${dangling.length} mounted skill link(s) dangle: ${dangling.slice(0, 5).join(', ')}`,
143	      're-run the skill mount (the update task does it) — a dangling link is a skill the session cannot load (#424)');
144	  }
145	  return pass('skill-links');
146	}
147	
148	export function probeScheduler(io) {
149	  const text = io.read(SCHEDULER);
150	  if (text === null) return skip('scheduler', 'no vendored scheduler workflow — this repo has not cut over to per-project scheduling');
151	  const crons = [...text.matchAll(/cron:\s*['"]?([^'"\n]+?)['"]?\s*$/gm)].map((m) => m[1].trim());
152	  if (crons.length !== 1) {
153	    return fail('scheduler', `the scheduler declares ${crons.length} cron schedules, expected exactly one`, 'keep a single hourly cron — the scheduler is the repo\'s only cron');
154	  }
155	  const parts = crons[0].split(/\s+/);
156	  if (parts.length !== 5 || !Number.isInteger(Number(parts[0]))) {
157	    return fail('scheduler', `the scheduler cron "${crons[0]}" does not parse as a 5-field expression with a fixed minute`,
158	      'set "<minute> * * * *" with the repo-hashed minute — an unparseable cron means the repo never runs a task again');
159	  }
160	  return pass('scheduler');
161	}
162	
163	export function probeMigrations(migrations) {
164	  if (migrations === null) return skip('migrations', 'no migrations registry reachable from here');
165	  if (migrations instanceof Error) {
166	    return fail('migrations', `the migrations registry failed to load: ${migrations.message}`,
167	      'a malformed record aborts every update run — fix or remove it');
168	  }
169	  return pass('migrations');
170	}
171	
172	// --- the I/O shell ---------------------------------------------------------
173	
174	function makeIo(root) {
175	  const abs = (p) => join(root, p);
176	  return {
177	    exists: (p) => existsSync(abs(p)),
178	    read: (p) => { try { return readFileSync(abs(p), 'utf8'); } catch { return null; } },
179	    // Symlinks under a directory whose targets do not resolve.
180	    dangling: (rel) => {
181	      const out = [];
182	      const walk = (dir) => {
183	        let entries = [];
184	        try { entries = readdirSync(abs(dir), { withFileTypes: true }); } catch { return; }
185	        for (const e of entries) {
186	          const p = `${dir}/${e.name}`;
187	          if (e.isSymbolicLink()) {
188	            try { realpathSync(abs(p)); } catch { out.push(p); }
189	          } else if (e.isDirectory()) walk(p);
190	        }
191	      };
192	      walk(rel);
193	      return out;
194	    },
195	    lstat: (p) => { try { return lstatSync(abs(p)); } catch { return null; } },
196	  };
197	}
198	
199	// Load the pack set and the migrations registry from whichever corpus this file
200	// is running out of — the canon root, or a consumer's vendored mount. Both are
201	// best-effort: a failure to reach them is a probe result, never a throw.
202	async function loadCorpus(root) {
203	  const corpus = dirname(dirname(fileURLToPath(import.meta.url))); // <corpus>/engine/ -> <corpus>
204	  let loaded = null;
205	  try {
206	    const { discoverPacks } = await import(pathToFileURL(join(corpus, 'engine/pack_loader/pack-registry.mjs')).href);
207	    loaded = await discoverPacks({ localRoot: root });
208	  } catch (e) { loaded = { packs: [], errors: [{ what: `the pack loader itself failed: ${e.message}`, fix: 'the engine is broken or half-vendored — re-run the update task' }] }; }
209	
210	  let migrations = null;
211	  // The registry moved under the engine with the engine/pack split; a mount that
212	  // has not converged since still carries the flat path, and probing it as absent
213	  // would report a HEALTHY-looking skip on a repo whose registry is right there.
214	  const regPath = [join(corpus, 'engine/migrations/registry.mjs'), join(corpus, 'migrations/registry.mjs')]
215	    .find((p) => existsSync(p));
216	  if (regPath) {
217	    try {
218	      const reg = await import(pathToFileURL(regPath).href);
219	      await reg.loadMigrations();
220	      migrations = true;
